class CloseInvoice {
	execute(id: string): void {
		const invoices = Container.get<InvoiceRepository>("InvoiceRepository");
		const clock = Container.get<Clock>("Clock");
		const invoice = invoices.find(id);
		invoice.close(clock.now());
		invoices.save(invoice);
	}
}

